import{_ as l,a0 as d,w as t,s as o,ao as c,I as p,x as e,a1 as a,A as i}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const S=JSON.parse('{"title":"為 Linux 用户準備的 FreeDOS 命令 | LCTT x X-CMD","titleTemplate":false,"description":"為 Linux 用户準備的 FreeDOS 命令 | LCTT (202112) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"為 Linux 用户準備的 FreeDOS 命令 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"為 Linux 用户準備的 FreeDOS 命令 | LCTT (202112) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202112/20210603 FreeDOS commands for Linux fans","title":"為 Linux 用户準備的 FreeDOS 命令","tag":"202112","desc":""},"relativePath":"202112/20210603 FreeDOS commands for Linux fans.md","filePath":"[post].md"}'),r={name:"202112/20210603 FreeDOS commands for Linux fans.md"};function u(h,s,g,k,f,x){const n=d("Link");return t(),o("div",null,[s[15]||(s[15]=c(`<h1 id="為-linux-用户準備的-freedos-命令" tabindex="-1">為 Linux 用户準備的 FreeDOS 命令 <a class="header-anchor" href="#為-linux-用户準備的-freedos-命令" aria-label="Permalink to “為 Linux 用户準備的 FreeDOS 命令”">​</a></h1><blockquote><p>如果你已經熟悉了 Linux 命令列，嘗試這些命令有助於輕鬆地進入 FreeDOS 。</p></blockquote><p><img src="https://img.linux.net.cn/data/attachment/album/202112/18/102331ubkem265eqz6u1mk.jpg" alt=""></p><p>如果你已經嘗試過 FreeDOS ，你可能已經被命令列所嚇倒。DOS 命令可能稍微不同於你所使用的 Linux 命令列，因此，使用它的命令列上需要學習一些新的命令。</p><p>但是對於 Linux 用户來説，它不是一種 “全新的” 體驗。在 FreeDOS 中，除了 DOS 命令之外，我們還包含一些已經熟悉的標準的 Unix 命令。因此，如果你已經熟悉了 Linux 命令列，嘗試這些命令有助於輕鬆地進入 FreeDOS ：</p><h3 id="在四周走走" tabindex="-1">在四周走走 <a class="header-anchor" href="#在四周走走" aria-label="Permalink to “在四周走走”">​</a></h3><p>在 FreeDOS 文件系統中使用 <code>cd</code> 命令來 <em>更改目錄</em> 。在 FreeDOS 上的用法在 Linux 上的用法基本相同。要更改到一個名稱為 <code>apps</code> 的子目錄，輸入 <code>cd apps</code> 。要回到先前的目錄，輸入 <code>cd ..</code> 。</p><p>在 FreeDOS 上導航瀏覽目錄和路徑是僅有的不同點，目錄分隔符是 <code>\\</code>（“反斜槓”）而不是你在 Linux 上使用的 <code>/</code> （“正斜槓”）。例如，讓我們假設你在 <code>\\devel</code> 目錄之中，你想移動到 <code>\\fdos</code> 目錄。這兩個目錄相對於 <em>根</em> 目錄而言是處於相同的 “層次” 之中的。因此，你可以輸入 <code>cd ..\\fdos</code> 來 “向後返回” 一個目錄層次（使用 <code>..</code>） ，然後再 “轉到” <code>fdos</code> 目錄。</p><p>要更改到一個新的目錄，你可以使用先前提到的反斜槓來替換需要給出的完整的路徑。如果你已經深入了另外一個路徑之中，並且只是像立即切換到新的位置，那麼這會是非常方便的。例如，要更改到 <code>\\temp</code> 目錄，你可以輸入 <code>cd \\temp</code> 。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;cd apps</span></span>
<span class="line"><span>C:\\APPS&gt;cd ..</span></span>
<span class="line"><span>C:\\&gt;cd devel</span></span>
<span class="line"><span>C:\\DEVEL&gt;cd ..\\fdos</span></span>
<span class="line"><span>C:\\FDOS&gt;cd \\temp</span></span>
<span class="line"><span>C:\\TEMP&gt;_</span></span></code></pre></div><p>在 FreeDOS 中，像大多數的 DOS 系統一樣，你可以在DOS 提示符中看到你的當前路徑。在 Linux 上，你的提示符可能類似於 <code>$</code> 。在 FreeDOS 上，提示符會列出當前的驅動器及其當前的路徑，接下來使用 <code>&gt;</code> 作為提示符（看做 Linux 上的 <code>$</code>）。</p><h3 id="列出和顯示文件" tabindex="-1">列出和顯示文件 <a class="header-anchor" href="#列出和顯示文件" aria-label="Permalink to “列出和顯示文件”">​</a></h3><p>在 Linux 上，列出當前目錄中文件的標準命令是 <code>ls</code> 命令。在 FreeDOS ，它是一個不同的命令： <code>dir</code> 。但是你可以創建一個 <em>別名</em> 來獲取一種與 <code>ls</code> 類似的行為。</p><p>要為另外一個命令創建一個別名，使用內置的 <code>alias</code> 命令。例如，使用此命令來為 <code>ls</code> 定義一個別名，這個別名將顯示一個目錄列表，與在 Linux 上使用 <code>ls</code> 類似：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;alias ls=dir /one /w /b /l</span></span>
<span class="line"><span>C:\\&gt;ls</span></span>
<span class="line"><span>[apps]    command.com   [devel]  fdauto.bat   fdconfig.sys</span></span>
<span class="line"><span>[fdos]    kernel.sys    [src]    [temp]</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>在 FreeDOS 上的命令選項格式與 Linux 稍微不同。在 Linux 上， 你使用一個連字符號（<code>-</code>）表示選項。但是在 FreeDOS 上，你使用一個正斜槓來表示選項。上面的 <code>alias</code> 命令使用斜杆槓字符 — 它們是 <code>dir</code> 的選項。<code>/one</code> 可選擇項告訴 <code>dir</code> 以某種方式排序（<code>o</code>）：先按名稱（<code>n</code>）再按擴展名（<code>e</code>）來排序一些文件和目錄。<code>/w</code> 使用一個 “寬” 目錄列表，<code>/b</code> 使用一種不帶有 <code>dir</code> 通常提供的其它信息的 “裸” 顯示，<code>/l</code> 指示 <code>dir</code> 以小寫字母的形式顯示文件和目錄。</p><p>注意，針對於 FreeDOS 的 <code>dir</code> 命令的命令列選項與針對於 Linux 的 <code>ls</code> 命令的命令列選項截然不同，因此，你不能像你在 Linux 上一樣精確地使用這個 <code>ls</code> 別名。例如，在 FreeDOS 上使用此別名輸入 <code>ls -l</code> 將產生一條 “文件未找到” 的錯誤，因為底層的 FreeDOS 的 <code>dir</code> 命令不能找到一個名稱為 <code>-l</code> 的文件。不過，對於基本的 “查看在我的系統上有哪些文件” 來説，這個 <code>ls</code> 別名已經足夠幫助 Linux 用户開始使用 FreeDOS 了。</p><p>類似地，你可以為 FreeDOS 的 <code>type</code> 命令創建一個別名，來像 Linux 的 <code>cat</code> 命令一樣工作。兩個重新都會顯示一個文本文件的內容。雖然 <code>type</code> 不支持你可能在 Linux 下使用的命令列選項，但是顯示一單個文件的基本用法是相同的。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\FDOS&gt;alias cat=type</span></span>
<span class="line"><span>C:\\FDOS&gt;cat version.fdi</span></span>
<span class="line"><span>PLATFORM=FreeDOS</span></span>
<span class="line"><span>VERSION=1.3-RC4</span></span>
<span class="line"><span>RELEASE=2021-04-30</span></span>
<span class="line"><span>C:\\FDOS&gt;</span></span></code></pre></div><h3 id="其它的類-unix-命令" tabindex="-1">其它的類 Unix 命令 <a class="header-anchor" href="#其它的類-unix-命令" aria-label="Permalink to “其它的類 Unix 命令”">​</a></h3><p>FreeDOS 包含一些精選的其它常見的類 Unix 命令，因此 Linux 用户將不會感覺到拘束。為在 FreeDOS 上使用這些 Linux 命令，你可能需要從 “FreeDOS Installer” - “My Package List Editor Software (FDIMPLES)” 軟件包管理器來安裝 “Unix Like Tools” 軟件包。</p><p><img src="https://opensource.com/sites/default/files/uploads/unix-like.png" alt="Installing the Unix-like package set" title="Installing the Unix-like package set"></p><p>（Jim Hall, CC-BY SA 4.0）</p><p>並不是所有的類 Unix 實用程序都能像在 Linux 上對應的實用程序一樣 <em>一致地</em> 工作。這就是我們稱其為 <em>類 Unix</em> 的原因。如果你將要使用一些深層次的命令列選項，你可能需要檢查其兼容性，不過，對於典型的用法是沒有問題的。開始在 FreeDOS 上使用這些類 Unix 命令：</p><p><code>cal</code> 命令是標準的 Unix 的日曆程序。例如，為顯示當前月份的日曆，只需要輸入 <code>cal</code> 。為查看一個具體指定的月份，將月份和年份作為參數予以給定：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;cal 6 1994</span></span>
<span class="line"><span></span></span>
<span class="line"><span>      June 1994    </span></span>
<span class="line"><span>Su Mo Tu We Th Fr Sa</span></span>
<span class="line"><span>          1  2  3  4</span></span>
<span class="line"><span> 5  6  7  8  9 10 11</span></span>
<span class="line"><span>12 13 14 15 16 17 18</span></span>
<span class="line"><span>19 20 21 22 23 24 25</span></span>
<span class="line"><span>26 27 28 29 30</span></span></code></pre></div><p>使用 <code>du</code> 命令來查看你的磁盤使用情況。這是 Linux 的 <code>du</code> 命令的簡單版本，並且不支持路徑以外的任何命令列選項。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;du -s apps</span></span>
<span class="line"><span>usage: du (start path)</span></span>
<span class="line"><span>C:\\&gt;du apps</span></span>
<span class="line"><span>    158784 C:\\APPS\\FED</span></span>
<span class="line"><span>         0 C:\\APPS</span></span>
<span class="line"><span>Total from C:\\APPS is 158784</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p><code>head</code> 命令顯示一個文件的前幾行。例如，這是一種確定一個文件是否包含正確數據的簡單方法。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:&gt;head fdauto.bat</span></span>
<span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>set DOSDIR=C&quot;\\FDOS</span></span>
<span class="line"><span>set LANG=EN</span></span>
<span class="line"><span>set TZ=UTC</span></span>
<span class="line"><span>set PATH=%dosdir%\\BIN</span></span>
<span class="line"><span>if exist %dosdir%\\LINKS\\NUL set PATH=%path%;%dosdir%\\LINKS</span></span>
<span class="line"><span>set NLSPATH=%dosdir%\\NLS</span></span>
<span class="line"><span>set HELPPATH=%dosdir%\\HELP</span></span>
<span class="line"><span>set TEMP=%dosdir%\\TEMP</span></span>
<span class="line"><span>set TMP=%TEMP%</span></span>
<span class="line"><span>C:\\&gt;</span></span></code></pre></div><p>要查看一個完整的文件，使用 <code>more</code> 命令，在 FreeDOS 上的默認文件查看器。這將一次顯示一屏的文件，然後在顯示下一屏的信息前，打印一個按下一次按鍵的提示。<code>more</code> 命令是一個非常簡單的文件查看器；在 Linux 上你可能已經使用過一個功能更全面的查看器，可以嘗試一下 <code>less</code> 命令。<code>less</code> 命令提供 “向後” 滾動一個文件的能力，以防你錯過一些東西。你還可以搜索具體指定的文本。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;less fdauto.bat</span></span>
<span class="line"><span>@ECHO OFF</span></span>
<span class="line"><span>set DOSDIR=C&quot;\\FDOS</span></span>
<span class="line"><span>set LANG=EN</span></span>
<span class="line"><span>set TZ=UTC</span></span>
<span class="line"><span>set PATH=%dosdir%\\BIN</span></span>
<span class="line"><span>if exist %dosdir%\\LINKS\\NUL set PATH=%path%;%dosdir%\\LINKS</span></span>
<span class="line"><span>set NLSPATH=%dosdir%\\NLS</span></span>
<span class="line"><span>set HELPPATH=%dosdir%\\HELP</span></span>
<span class="line"><span>set TEMP=%dosdir%\\TEMP</span></span>
<span class="line"><span>set TMP=%TEMP%</span></span>
<span class="line"><span>[...]</span></span></code></pre></div><p>如果在你的程序路徑變量（<code>PATH</code>）中有很多的目錄，並且不確定某個程序是從哪裏運行的，你可以使用 <code>which</code> 命令。這個命令將掃描程序路徑變量，並且將打印出你正在查找的程序的完整的位置。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>C:\\&gt;which less</span></span>
<span class="line"><span>less    C:\\&gt;FDOS\\BIN\\LESS.EXE</span></span>
<span class="line"><span>C:\\&gt;_</span></span></code></pre></div><p>FreeDOS 1.3 RC4 包含其它的類 Unix 命令，你可能會在其它更特殊的情況下使用。這些命令包括：</p><ul><li><code>bc</code>：任意精度數字處理語言</li><li><code>sed</code>：流編輯器</li><li><code>grep</code> 和 <code>xgrep</code>：使用正則表達式搜索一個文本文件</li><li><code>md5sum</code>：生成一個文件的一個 MD5 簽名</li><li><code>nro</code>：簡單排版，使用 nroff 宏</li><li><code>sleep</code>：暫停系統幾秒鐘</li><li><code>tee</code>：保存一個命令列流的副本</li><li><code>touch</code>：修改一個文件的時間戳</li><li><code>trch</code>：轉換單個字符（像 Linux 的 <code>tr</code> 一樣）</li><li><code>uptime</code>：報告你 FreeDOS 系統已經運行多長的時間</li></ul><h3 id="在你控制下的-freedos" tabindex="-1">在你控制下的 FreeDOS <a class="header-anchor" href="#在你控制下的-freedos" aria-label="Permalink to “在你控制下的 FreeDOS”">​</a></h3><p>FreeDOS ，像 Linux 和 BSD 一樣，是開源的。不管你是想通過學習一種新的命令列交互方式來挑戰你自己，還是想再去熟悉令人舒適的類 Unix 工具，FreeDOS 都是一款有趣的值得嚐鮮的操作系統。嘗試一下！</p><hr>`,39)),p("p",null,[s[1]||(s[1]=e("via: ",-1)),a(n,{href:"https://opensource.com/article/21/6/freedos-linux-users"},{default:i(()=>[...s[0]||(s[0]=[e("https://opensource.com/article/21/6/freedos-linux-users",-1)])]),_:1})]),p("p",null,[s[6]||(s[6]=e("作者：",-1)),a(n,{href:"https://opensource.com/users/jim-hall"},{default:i(()=>[...s[2]||(s[2]=[e("Jim Hall",-1)])]),_:1}),s[7]||(s[7]=e(" 選題：",-1)),a(n,{href:"https://github.com/lujun9972"},{default:i(()=>[...s[3]||(s[3]=[e("lujun9972",-1)])]),_:1}),s[8]||(s[8]=e(" 譯者：",-1)),a(n,{href:"https://github.com/robsean"},{default:i(()=>[...s[4]||(s[4]=[e("robsean",-1)])]),_:1}),s[9]||(s[9]=e(" 校對：",-1)),a(n,{href:"https://github.com/wxy"},{default:i(()=>[...s[5]||(s[5]=[e("wxy",-1)])]),_:1})]),p("p",null,[s[12]||(s[12]=e("本文由 ",-1)),a(n,{href:"https://github.com/LCTT/TranslateProject"},{default:i(()=>[...s[10]||(s[10]=[e("LCTT",-1)])]),_:1}),s[13]||(s[13]=e(" 原創編譯，",-1)),a(n,{href:"https://linux.cn/"},{default:i(()=>[...s[11]||(s[11]=[e("Linux中國",-1)])]),_:1}),s[14]||(s[14]=e(" 榮譽推出",-1))])])}const L=l(r,[["render",u]]);export{S as __pageData,L as default};
